static void sms_detail_send_del_file(uint32_t file_index)
{
    DIR *           dir;

    struct dirent * dinfo = NULL;
    char            path[40];
    int32_t         ret;

    dir                 = opendir(TELE_SMS_DATA_SEND_FOLDER_PATH);

    while (NULL != (dinfo = readdir(dir))) {
        if (file_index != dinfo->d_off)
            continue;

        if (NULL != dinfo) {
            strcpy(path,TELE_SMS_DATA_SEND_FOLDER_PATH);
            strcat(path,"/");
            strcat(path,dinfo->d_name);


            }

        closedir(dir);
        break;
        }

    ret                 = unlink(path);

    if (ret == 0)
        sms_data_box_count_reduce(TELE_SMS_DATA_SEND_FOLDER_PATH);
}


static void remind_timer_callback_sms_send_del(screen_remind_param_t * p_param)
{

    alv_am_win_exit_action(NULL,"detail_send_option",NULL);
    alv_am_win_exit_action(NULL,"detail_send",NULL);
    alv_am_win_exit_action(NULL,"list_send",NULL);

    if (is_tele_sms_data_send_empty()) {
        alv_am_win_exit_current(NULL);
        sms_menu_remind_box_empty(2);
        }
    else {
        alv_am_win_jump_action(NULL,"list_send",NULL);
        }
}

